// src/features/Sales/pages/AccountingManagement.jsx
import React, { useState } from 'react';
import {
  Container,
  Typography,
  Divider,
  Box,
  Tabs,
  Tab,
  Paper,
  Grid,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Button,
  FormControl,
  InputLabel,
  Select,
  MenuItem
} from '@mui/material';
import CalculateIcon from '@mui/icons-material/Calculate';

// Función local para formatear moneda
const formatCurrency = (value) => {
  return new Intl.NumberFormat('es-MX', {
    style: 'currency',
    currency: 'MXN'
  }).format(value || 0);
};

const AccountingManagement = () => {
  const [tabValue, setTabValue] = useState(0);
  const [taxFormData, setTaxFormData] = useState({
    income: '',
    expenses: '',
    taxRegime: 'rif',
    period: 'month'
  });
  const [taxResults, setTaxResults] = useState(null);

  const handleTabChange = (event, newValue) => {
    setTabValue(newValue);
  };

  const handleTaxFormChange = (e) => {
    const { name, value } = e.target;
    setTaxFormData(prev => ({ ...prev, [name]: value }));
  };
  
  const handleTaxCalculation = (e) => {
    e.preventDefault();
    
    // Cálculo simplificado para demostración
    const income = parseFloat(taxFormData.income) || 0;
    const expenses = parseFloat(taxFormData.expenses) || 0;
    const taxableIncome = income - expenses;
    
    // Tasas de impuestos simplificadas
    const vatRate = 0.16;
    const incomeTaxRate = taxFormData.taxRegime === 'rif' ? 0.05 : 
                          taxFormData.taxRegime === 'resico' ? 0.02 : 0.30;
    
    const vat = income * vatRate;
    const incomeTax = taxableIncome * incomeTaxRate;
    
    setTaxResults({
      taxableIncome,
      vat,
      incomeTax,
      totalTax: vat + incomeTax
    });
  };

  // Datos de ejemplo para el balance
  const balanceData = {
    assets: [
      { name: 'Efectivo', amount: 10000 },
      { name: 'Cuentas por Cobrar', amount: 5000 },
      { name: 'Inventario', amount: 15000 }
    ],
    liabilities: [
      { name: 'Cuentas por Pagar', amount: 8000 },
      { name: 'Préstamos', amount: 10000 }
    ],
    equity: [
      { name: 'Capital', amount: 12000 }
    ],
    totalAssets: 30000,
    totalLiabilities: 18000,
    totalEquity: 12000
  };

  // Datos de ejemplo para el estado de resultados
  const statementData = {
    revenue: [
      { name: 'Ventas de Productos', amount: 50000 },
      { name: 'Servicios', amount: 20000 }
    ],
    expenses: [
      { name: 'Costo de Ventas', amount: 30000 },
      { name: 'Gastos Operativos', amount: 15000 },
      { name: 'Gastos Administrativos', amount: 10000 }
    ],
    totalRevenue: 70000,
    totalExpenses: 55000,
    grossProfit: 40000,
    netIncome: 15000
  };

  // Componente de Balance General
  const SimpleBalanceSheet = () => (
    <Paper sx={{ p: 2, width: '100%' }}>
      <Typography variant="h6" gutterBottom>
        Balance General Simplificado
      </Typography>
      
      <Typography variant="subtitle1" sx={{ mt: 2 }}>
        Activos
      </Typography>
      <TableContainer>
        <Table size="small">
          <TableBody>
            {balanceData.assets.map((item, index) => (
              <TableRow key={index}>
                <TableCell>{item.name}</TableCell>
                <TableCell align="right">{formatCurrency(item.amount)}</TableCell>
              </TableRow>
            ))}
            <TableRow>
              <TableCell sx={{ fontWeight: 'bold' }}>Total Activos</TableCell>
              <TableCell align="right" sx={{ fontWeight: 'bold' }}>
                {formatCurrency(balanceData.totalAssets)}
              </TableCell>
            </TableRow>
          </TableBody>
        </Table>
      </TableContainer>
      
      <Typography variant="subtitle1" sx={{ mt: 2 }}>
        Pasivos
      </Typography>
      <TableContainer>
        <Table size="small">
          <TableBody>
            {balanceData.liabilities.map((item, index) => (
              <TableRow key={index}>
                <TableCell>{item.name}</TableCell>
                <TableCell align="right">{formatCurrency(item.amount)}</TableCell>
              </TableRow>
            ))}
            <TableRow>
              <TableCell sx={{ fontWeight: 'bold' }}>Total Pasivos</TableCell>
              <TableCell align="right" sx={{ fontWeight: 'bold' }}>
                {formatCurrency(balanceData.totalLiabilities)}
              </TableCell>
            </TableRow>
          </TableBody>
        </Table>
      </TableContainer>
      
      <Typography variant="subtitle1" sx={{ mt: 2 }}>
        Capital
      </Typography>
      <TableContainer>
        <Table size="small">
          <TableBody>
            {balanceData.equity.map((item, index) => (
              <TableRow key={index}>
                <TableCell>{item.name}</TableCell>
                <TableCell align="right">{formatCurrency(item.amount)}</TableCell>
              </TableRow>
            ))}
            <TableRow>
              <TableCell sx={{ fontWeight: 'bold' }}>Total Capital</TableCell>
              <TableCell align="right" sx={{ fontWeight: 'bold' }}>
                {formatCurrency(balanceData.totalEquity)}
              </TableCell>
            </TableRow>
          </TableBody>
        </Table>
      </TableContainer>
    </Paper>
  );

  // Componente de Estado de Resultados
  const IncomeStatement = () => {
    const renderSection = (title, items, total) => (
      <Box sx={{ mb: 3 }}>
        <Typography variant="subtitle1" sx={{ fontWeight: 'bold', mb: 1 }}>
          {title}
        </Typography>
        
        {items.map((item, index) => (
          <Box key={index} sx={{ display: 'flex', justifyContent: 'space-between', mb: 0.5 }}>
            <Typography variant="body2">{item.name}</Typography>
            <Typography variant="body2">{formatCurrency(item.amount)}</Typography>
          </Box>
        ))}
        
        <Box sx={{ display: 'flex', justifyContent: 'space-between', mt: 1, fontWeight: 'bold' }}>
          <Typography variant="body2">Total {title}</Typography>
          <Typography variant="body2">{formatCurrency(total)}</Typography>
        </Box>
      </Box>
    );

    return (
      <Paper sx={{ p: 2, width: '100%' }}>
        <Typography variant="h6" gutterBottom>
          Estado de Resultados
        </Typography>
        
        <Divider sx={{ mb: 2 }} />
        
        {renderSection('Ingresos', statementData.revenue, statementData.totalRevenue)}
        
        <Divider sx={{ my: 2 }} />
        
        {renderSection('Gastos', statementData.expenses, statementData.totalExpenses)}
        
        <Divider sx={{ my: 2 }} />
        
        <Box sx={{ mb: 1 }}>
          <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
            <Typography variant="subtitle1">Utilidad Bruta</Typography>
            <Typography variant="subtitle1">{formatCurrency(statementData.grossProfit)}</Typography>
          </Box>
        </Box>
        
        <Box sx={{ mb: 3 }}>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', fontWeight: 'bold' }}>
            <Typography variant="subtitle1">Utilidad Neta</Typography>
            <Typography 
              variant="subtitle1" 
              color={statementData.netIncome >= 0 ? 'success.main' : 'error.main'}
            >
              {formatCurrency(statementData.netIncome)}
            </Typography>
          </Box>
        </Box>
      </Paper>
    );
  };

  // Componente de Calculadora de Impuestos
  const TaxCalculator = () => (
    <Paper sx={{ p: 2, width: '100%' }}>
      <Typography variant="h6" gutterBottom>
        Calculadora de Impuestos
      </Typography>
      
      <Divider sx={{ mb: 3 }} />
      
      <form onSubmit={handleTaxCalculation}>
        <Grid container spacing={3}>
          <Grid item xs={12} md={6}>
            <TextField
              fullWidth
              label="Ingresos"
              name="income"
              value={taxFormData.income}
              onChange={handleTaxFormChange}
              type="number"
              InputProps={{ inputProps: { min: 0, step: 0.01 } }}
              required
            />
          </Grid>
          
          <Grid item xs={12} md={6}>
            <TextField
              fullWidth
              label="Gastos Deducibles"
              name="expenses"
              value={taxFormData.expenses}
              onChange={handleTaxFormChange}
              type="number"
              InputProps={{ inputProps: { min: 0, step: 0.01 } }}
              required
            />
          </Grid>
          
          <Grid item xs={12} md={6}>
            <FormControl fullWidth>
              <InputLabel id="tax-regime-label">Régimen Fiscal</InputLabel>
              <Select
                labelId="tax-regime-label"
                name="taxRegime"
                value={taxFormData.taxRegime}
                onChange={handleTaxFormChange}
                label="Régimen Fiscal"
              >
                <MenuItem value="rif">RIF</MenuItem>
                <MenuItem value="resico">RESICO</MenuItem>
                <MenuItem value="general">Régimen General</MenuItem>
              </Select>
            </FormControl>
          </Grid>
          
          <Grid item xs={12} md={6}>
            <FormControl fullWidth>
              <InputLabel id="period-label">Periodo</InputLabel>
              <Select
                labelId="period-label"
                name="period"
                value={taxFormData.period}
                onChange={handleTaxFormChange}
                label="Periodo"
              >
                <MenuItem value="month">Mensual</MenuItem>
                <MenuItem value="bimonthly">Bimestral</MenuItem>
                <MenuItem value="quarter">Trimestral</MenuItem>
                <MenuItem value="year">Anual</MenuItem>
              </Select>
            </FormControl>
          </Grid>
          
          <Grid item xs={12}>
            <Button
              type="submit"
              variant="contained"
              color="primary"
              startIcon={<CalculateIcon />}
              fullWidth
            >
              Calcular Impuestos
            </Button>
          </Grid>
        </Grid>
      </form>
      
      {taxResults && (
        <Box sx={{ mt: 4 }}>
          <Divider sx={{ mb: 2 }} />
          
          <Typography variant="h6" gutterBottom>
            Resultados del Cálculo
          </Typography>
          
          <Grid container spacing={2}>
            <Grid item xs={12} md={6}>
              <Box sx={{ bgcolor: 'background.paper', p: 2, borderRadius: 1 }}>
                <Typography variant="subtitle2" color="text.secondary" gutterBottom>
                  Base Gravable
                </Typography>
                <Typography variant="h6">
                  {formatCurrency(taxResults.taxableIncome)}
                </Typography>
              </Box>
            </Grid>
            
            <Grid item xs={12} md={6}>
              <Box sx={{ bgcolor: 'background.paper', p: 2, borderRadius: 1 }}>
                <Typography variant="subtitle2" color="text.secondary" gutterBottom>
                  IVA por Pagar
                </Typography>
                <Typography variant="h6">
                  {formatCurrency(taxResults.vat)}
                </Typography>
              </Box>
            </Grid>
            
            <Grid item xs={12} md={6}>
              <Box sx={{ bgcolor: 'background.paper', p: 2, borderRadius: 1 }}>
                <Typography variant="subtitle2" color="text.secondary" gutterBottom>
                  ISR por Pagar
                </Typography>
                <Typography variant="h6">
                  {formatCurrency(taxResults.incomeTax)}
                </Typography>
              </Box>
            </Grid>
            
            <Grid item xs={12} md={6}>
              <Box sx={{ bgcolor: 'error.light', p: 2, borderRadius: 1 }}>
                <Typography variant="subtitle2" gutterBottom>
                  Total a Pagar
                </Typography>
                <Typography variant="h6" fontWeight="bold">
                  {formatCurrency(taxResults.totalTax)}
                </Typography>
              </Box>
            </Grid>
          </Grid>
        </Box>
      )}
    </Paper>
  );

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Typography variant="h4" gutterBottom>
        Gestión Contable
      </Typography>
      <Divider sx={{ mb: 4 }} />

      <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 3 }}>
        <Tabs value={tabValue} onChange={handleTabChange} aria-label="accounting tabs">
          <Tab label="Balance General" />
          <Tab label="Estado de Resultados" />
          <Tab label="Calculadora de Impuestos" />
        </Tabs>
      </Box>

      <Box sx={{ mt: 2 }}>
        {tabValue === 0 && <SimpleBalanceSheet />}
        {tabValue === 1 && <IncomeStatement />}
        {tabValue === 2 && <TaxCalculator />}
      </Box>
    </Container>
  );
};

export default AccountingManagement;